@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class Frequency_ESTest extends Frequency_ESTest_scaffolding {

    private static final long TIMEOUT_MS = 4000;

    // ---------------------------------------------------------------------
    // equals / hashCode
    // ---------------------------------------------------------------------

    @Test(timeout = TIMEOUT_MS)
    public void twoEmptyDistributionsAreEqual() throws Throwable {
        Frequency<Integer> first = new Frequency<Integer>();
        Frequency<Integer> second = new Frequency<Integer>();

        assertTrue(first.equals(second));
    }

    @Test(timeout = TIMEOUT_MS)
    public void distributionIsEqualToItself() throws Throwable {
        Frequency<Integer> frequency = new Frequency<Integer>();

        assertTrue(frequency.equals(frequency));
    }

    @Test(timeout = TIMEOUT_MS)
    public void distributionIsNotEqualToUnrelatedObject() throws Throwable {
        Frequency<Integer> frequency = new Frequency<Integer>();

        assertFalse(frequency.equals(new Object()));
    }

    @Test(timeout = TIMEOUT_MS)
    public void hashCodeOfEmptyDistributionDoesNotThrow() throws Throwable {
        Frequency<Integer> frequency = new Frequency<Integer>();

        frequency.hashCode();
    }

    // ---------------------------------------------------------------------
    // merge
    // ---------------------------------------------------------------------

    @Test(timeout = TIMEOUT_MS)
    public void mergingACollectionLeavesThatCollectionUnchanged() throws Throwable {
        Frequency<Integer> frequency = new Frequency<Integer>();
        frequency.incrementValue(0, 0L);

        LinkedList<Frequency<Integer>> toMerge = new LinkedList<Frequency<Integer>>();
        toMerge.add(frequency);

        frequency.merge((Collection<Frequency<Integer>>) toMerge);

        assertEquals(1, toMerge.size());
    }

    // ---------------------------------------------------------------------
    // getMode
    // ---------------------------------------------------------------------

    @Test(timeout = TIMEOUT_MS)
    public void modeIsTheSingleValueWithTheHighestCount() throws Throwable {
        Frequency<Integer> frequency = new Frequency<Integer>();
        frequency.incrementValue(166, 0L); // count stays 0
        frequency.incrementValue(0, 1L);   // count becomes 1 -> the mode

        List<Integer> mode = frequency.getMode();

        assertTrue(mode.contains(0));
        assertEquals(1, mode.size());
    }

    // ---------------------------------------------------------------------
    // getCumFreq
    // ---------------------------------------------------------------------

    @Test(timeout = TIMEOUT_MS)
    public void cumulativeFrequencyForValueFallingBetweenEntriesIsZero() throws Throwable {
        Frequency<Integer> frequency = new Frequency<Integer>();
        frequency.incrementValue(-2146457125, 0L);
        frequency.incrementValue(221, -1L);

        assertEquals(0L, frequency.getCumFreq(0));
    }

    @Test(timeout = TIMEOUT_MS)
    public void cumulativeFrequencyAtTheFirstValueIsZeroWhenItHasNoCount() throws Throwable {
        Frequency<Integer> frequency = new Frequency<Integer>();
        frequency.incrementValue(-2146457125, 0L);
        frequency.incrementValue(0, -1L);

        assertEquals(0L, frequency.getCumFreq(-2146457125));
    }

    @Test(timeout = TIMEOUT_MS)
    public void cumulativeFrequencyBelowTheOnlyValueIsZero() throws Throwable {
        Frequency<Integer> frequency = new Frequency<Integer>();
        frequency.addValue(1587);

        // The system property does not exist, so Integer.getInteger returns the
        // supplied default of 123, which is smaller than the only recorded value.
        Integer lookup = Integer.getInteger("Value \t Freq. \t Pct. \t Cum Pct. \n", 123);

        assertEquals(0L, frequency.getCumFreq(lookup));
    }

    @Test(timeout = TIMEOUT_MS)
    public void cumulativeFrequencyAboveTheLastValueEqualsTotalCount() throws Throwable {
        Frequency<Integer> frequency = new Frequency<Integer>();
        frequency.addValue(1587);

        assertEquals(1L, frequency.getCumFreq(1905));
    }

    @Test(timeout = TIMEOUT_MS)
    public void cumulativeFrequencyOfNullIsZeroForEmptyDistribution() throws Throwable {
        Frequency<Integer> frequency = new Frequency<Integer>();

        assertEquals(0L, frequency.getCumFreq((Integer) null));
    }

    // ---------------------------------------------------------------------
    // getCumPct / getPct / getCount on an empty distribution
    // ---------------------------------------------------------------------

    @Test(timeout = TIMEOUT_MS)
    public void cumulativePercentageIsNaNForEmptyDistribution() throws Throwable {
        Frequency<Integer> frequency = new Frequency<Integer>();

        assertEquals(Double.NaN, frequency.getCumPct(0), 0.01);
    }

    @Test(timeout = TIMEOUT_MS)
    public void percentageIsNaNForEmptyDistribution() throws Throwable {
        Frequency<Integer> frequency = new Frequency<Integer>();

        assertEquals(Double.NaN, frequency.getPct(0), 0.01);
    }

    @Test(timeout = TIMEOUT_MS)
    public void countOfUnseenValueIsZero() throws Throwable {
        Frequency<Integer> frequency = new Frequency<Integer>();

        assertEquals(0L, frequency.getCount(0));
    }

    // ---------------------------------------------------------------------
    // toString
    // ---------------------------------------------------------------------

    @Test(timeout = TIMEOUT_MS)
    public void toStringRendersHeaderAndASingleHundredPercentRow() throws Throwable {
        @SuppressWarnings("unchecked")
        Comparator<Integer> comparator = mock(Comparator.class, new ViolatedAssumptionAnswer());
        doReturn(0, 0, 0, 0, 0).when(comparator).compare(anyInt(), anyInt());

        Frequency<Integer> frequency = new Frequency<Integer>(comparator);
        frequency.addValue(46);

        String expected = "Value \t Freq. \t Pct. \t Cum Pct. \n46\t1\t100%\t100%\n";
        assertEquals(expected, frequency.toString());
    }

    // ---------------------------------------------------------------------
    // clear / getUniqueCount
    // ---------------------------------------------------------------------

    @Test(timeout = TIMEOUT_MS)
    public void clearingAnEmptyDistributionDoesNotThrow() throws Throwable {
        Frequency<Integer> frequency = new Frequency<Integer>();

        frequency.clear();
    }

    @Test(timeout = TIMEOUT_MS)
    public void uniqueCountOfEmptyDistributionIsZero() throws Throwable {
        Frequency<Integer> frequency = new Frequency<Integer>();

        assertEquals(0, frequency.getUniqueCount());
    }
}
